                Method m = obj.getClass().getMethod(methodName);
                return m.invoke(obj);
            } catch (Exception ex) {
                // Fallback to direct field access
                try {
                    Field f = obj.getClass().getDeclaredField(propName);
                    f.setAccessible(true);
                    return f.get(obj);
                } catch (Exception exc) {
                    throw new RuntimeException(exc);
                }
            }
        }
