                + " name=\"Test\" pageWidth=\"595\" pageHeight=\"842\" columnWidth=\"555\" "
                + " leftMargin=\"20\" rightMargin=\"20\" topMargin=\"20\" bottomMargin=\"20\">"
                + "<queryString>SELECT 1</queryString>"
                + "<field name=\"F1\" class=\"java.lang.String\"/>"
                + "<title>"
                + "<band height=\"50\">"
                + "<staticText>"
                + "<reportElement x=\"0\" y=\"0\" width=\"200\" height=\"50\"/>"
                + "<textElement/>"
                + "<text><![CDATA[Test Jasper]]></text>"
                + "</staticText>"
                + "</band>"
                + "</title>"
                + "<detail>"
                + "<band height=\"20\">"
                + "<textField>"
                + "<reportElement x=\"0\" y=\"0\" width=\"200\" height=\"20\"/>"
                + "<textFieldExpression><![CDATA[$F{F1}]]></textFieldExpression>"
                + "</textField>"
                + "</band>"
                + "</detail>"
                + "</jasperReport>";

        // Compile JRXML to JasperReport
        JasperReport report = JasperCompileManager.compileReport(new ByteArrayInputStream(jrxml.getBytes(StandardCharsets.UTF_8)));

        // Write the compiled report to a resource path on the classpath (target/test-classes)
        File dir = new File("target/test-classes/reports");
        dir.mkdirs();
        File jasperFile = new File(dir, "test_report.jasper");
